mapper.select:
SELECT
FROM education_achievements header JOIN users owner ON owner.user_id = header.teacher_user_id JOIN employment_rate_improvement_achievement_details detail ON detail.achievement_id = header.achievement_id WHERE header.achievement_type = 'EMPLOYMENT_RATE_IMPROVEMENT' AND header.deleted_yn = 'N'
ORDER BY header.achievement_date DESC, header.achievement_id DESC LIMIT #{criteria.safePageSize} OFFSET #{criteria.offset}

mapper.update:
UPDATE employment_rate_improvement_achievement_details
SET special_lecture_start_date = #{specialLectureStartDate},
    special_lecture_end_date = #{specialLectureEndDate},
    mock_exam_question_period = #{mockExamQuestionPeriod}
WHERE achievement_id = #{achievementId}
